import{_ as a}from"./chunks/picker-pick.C3z1OD5-.js";import{_ as s,C as n,o as i,c as r,j as t,a as c,E as h,a6 as l}from"./chunks/framework.CCKCzdWs.js";const y=JSON.parse('{"title":"Pick an element","description":"Pick an element on the live page with Piwi Picker: its ranked locators, each checked against the page, with the action, the assertion and the context a test or an agent needs.","frontmatter":{"title":"Pick an element","description":"Pick an element on the live page with Piwi Picker: its ranked locators, each checked against the page, with the action, the assertion and the context a test or an agent needs.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/pick-an-element.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/pick-an-element.html"}],["meta",{"property":"og:title","content":"Pick an element | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Pick an element on the live page with Piwi Picker: its ranked locators, each checked against the page, with the action, the assertion and the context a test or an agent needs."}]]},"headers":[],"relativePath":"features/pick-an-element.md","filePath":"features/pick-an-element.md","lastUpdated":1793035357000}'),d={name:"features/pick-an-element.md"};function p(m,e,g,u,f,k){const o=n("Needs");return i(),r("div",null,[e[0]||(e[0]=t("h1",{id:"pick-an-element",tabindex:"-1"},[c("Pick an element "),t("a",{class:"header-anchor",href:"#pick-an-element","aria-label":'Permalink to "Pick an element"'},"​")],-1)),h(o,{extension:""}),e[1]||(e[1]=l('<p><strong>Pick an element</strong>, in the <a href="./extension.html">Piwi Picker</a> popup or with its shortcut, ranks the Playwright locators of one element of the page you are looking at, checks each against the page, and writes what a test needs around it.</p><figure><img src="'+a+'" alt="The ranked locators of a Checkout button, the unique one first"><figcaption>Pick an element: the locator that finds exactly one element comes first.</figcaption></figure><h2 id="how-a-pick-works" tabindex="-1">How a pick works <a class="header-anchor" href="#how-a-pick-works" aria-label="Permalink to &quot;How a pick works&quot;">​</a></h2><p>Hover highlights, a click picks. The pick snaps to the nearest actionable ancestor (the text inside a button picks the button), and ↑/↓ walk the DOM tree, showing the locator each step would produce. When a locator that is not brittle already finds the element alone, the results open at once, and <strong>Scope to a parent…</strong> in them opens the <strong>anchors</strong> step: stable parents to scope the locator to, with a live match count, after which the results show again with the scoped locators. When none finds it alone, the anchors step comes first.</p><p><strong>Enter</strong> picks too: the highlighted element when the pointer is on one, otherwise the element that has the keyboard focus, so a control reached with Tab is picked without the mouse. <strong>Esc</strong> cancels the pick.</p><p>Elements inside a web component&#39;s open shadow root are picked like any other: ↑ walks out of the shadow root through its host element, and the anchors step lists the host and its parents and counts the matches inside open shadow roots, as Playwright&#39;s locators do.</p><p>Every candidate uses the names Playwright computes (a tab with a count badge is <code>{ name: &#39;Regressions 5&#39; }</code>), is scored as the dashboard scores locators, and run against the page. Those that find only the picked element come first. One that also finds others is narrowed, trying in order:</p><ul><li>the exact name or text, then the element&#39;s own text as a filter;</li><li>a parent whose test id is unique on the page;</li><li>the repeated row, list item or card the element sits in, picked by a short text it shows and its siblings do not (a cell, a heading, a visible text before a hidden one), or by its own <code>aria-label</code>: <code>getByTestId(&#39;product-card&#39;).filter({ hasText: &#39;Blue mug&#39; }).getByRole(&#39;button&#39;, { name: &#39;Add to cart&#39; })</code>;</li><li>its landmark, a named dialog or a named row.</li></ul><p>Only when none of these finds it alone is it offered with <code>.first()</code> or <code>.nth()</code>, and a warning.</p><p>While the results are open, the picked element stays outlined on the page, and the results move to the other side of the page when they would cover it. <strong>Pick another</strong> closes them and starts picking the next element, without going back to the popup or the shortcut.</p><p>Each locator leads with a word: <code>stable</code>, <code>could break</code> or <code>brittle</code> for one that finds the element alone, by what the stability rules say of it, and <code>unique by position</code>, <code>3 matches</code> or <code>not checked</code> otherwise, the words the DevTools sidebar uses. Its <strong>Details</strong> give the reasons (<code>unique · brittle: CSS class</code>) and the stability score.</p><p>Copy the result as the bare locator, an action line or an assertion; <strong>Copy all</strong> copies every ranked locator for a project&#39;s <a href="./locator-usage.html#the-locators-page">Locators page</a>. The action is the one the element calls for: <code>fill</code> with what a field holds (<code>&#39;value&#39;</code> for an empty field or a password), <code>check</code> for a checkbox or a radio, <code>selectOption</code> for a select, <code>click</code> for anything else. The assertion is the element&#39;s first <a href="#assertion-suggester">suggestion</a>, and <code>toHaveCount</code> for a locator that finds several elements. Each button names what it writes, such as <strong>Action (fill)</strong> or <strong>Assertion (toHaveText)</strong>. <strong>Add to session</strong> names a locator for the session that the DevTools Piwi panel&#39;s Session tab lists and copies as a page object, as the Elements sidebar does (see <a href="./devtools.html">Developer tools</a>).</p><h2 id="multi-pick" tabindex="-1">Multi-pick <a class="header-anchor" href="#multi-pick" aria-label="Permalink to &quot;Multi-pick&quot;">​</a></h2><p>Pick two or three similar items (rows, cards) to get the pattern they share, such as <code>getByRole(&#39;row&#39;).filter({ hasText: … })</code>. Pick the same button in two rows or cards (Delete, Add to cart) and the pattern is the button inside the repeated row or card, with how many elements it finds on the page: <code>getByTestId(&#39;product-card&#39;).getByRole(&#39;button&#39;, { name: &#39;Add to cart&#39; })</code>, then each pick as its card filtered by a text only that card shows, such as its heading. It warns when only <code>.nth()</code> could tell them apart.</p><h2 id="assertion-suggester" tabindex="-1">Assertion suggester <a class="header-anchor" href="#assertion-suggester" aria-label="Permalink to &quot;Assertion suggester&quot;">​</a></h2><p>Pick an element to get the <code>expect(...)</code> candidates that apply to it, most telling first (<code>toHaveValue</code>, <code>toBeChecked</code>, <code>toContainText</code> with the start of a long text, <code>toHaveText</code>, <code>toHaveAccessibleName</code>, <code>toBeVisible</code>), built on its top-ranked locator. <code>toHaveAccessibleName</code> is offered only for an element that has a name, as Playwright computes it: a paragraph takes none from its text, a field takes its label&#39;s.</p><h2 id="copy-context-for-agent" tabindex="-1">Copy context for agent <a class="header-anchor" href="#copy-context-for-agent" aria-label="Permalink to &quot;Copy context for agent&quot;">​</a></h2><p>Pick an element to copy one block for a coding agent: the page URL, the element and every ranked locator.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./extension.html">Browser extension</a>: the other tools, the permissions and the limits</li><li><a href="./devtools.html">Developer tools</a>: the same ranking for the element selected in DevTools</li><li><a href="./lint-overlay.html">Lint overlay</a>: the elements no stable locator finds alone</li><li><a href="/reference/locator-stability.html">Locator stability</a>: the rules behind the words</li><li><a href="/recipes/broken-locator.html">Fix a broken locator</a>: from a failing locator to the one to use instead</li></ul>',20))])}const x=s(d,[["render",p]]);export{y as __pageData,x as default};
